import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.*;import java.io.*;
public class EventRegistrationApp extends JFrame {
 private final JTextField student=new JTextField(12);private final JComboBox<String> event=new JComboBox<>(new String[]{"Music","Dance","Sports","Coding"});
 private final DefaultTableModel model=new DefaultTableModel(new String[]{"Student ID","Event"},0);private final JTable table=new JTable(model);private final java.util.List<String[]> records=new ArrayList<>();
 public EventRegistrationApp(){super("Campus Event Registration");setLayout(new BorderLayout());JPanel form=new JPanel();form.add(new JLabel("Student ID"));form.add(student);form.add(event);JButton register=new JButton("Register");form.add(register);add(form,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);
 JMenuBar bar=new JMenuBar();JMenu file=new JMenu("File");JMenuItem export=new JMenuItem("Export CSV");file.add(export);bar.add(file);JMenu view=new JMenu("View");JMenuItem filter=new JMenuItem("Filter by Event");view.add(filter);bar.add(view);setJMenuBar(bar);
 register.addActionListener(e->register());filter.addActionListener(e->filter());export.addActionListener(e->exportCsv());setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(550,350);setLocationRelativeTo(null);}
 private void register(){String id=student.getText().trim(),ev=(String)event.getSelectedItem();if(id.isEmpty()){JOptionPane.showMessageDialog(this,"Student ID is required");return;}for(String[]r:records)if(r[0].equalsIgnoreCase(id)&&r[1].equals(ev)){JOptionPane.showMessageDialog(this,"Duplicate registration rejected");return;}records.add(new String[]{id,ev});model.addRow(new Object[]{id,ev});student.setText("");JOptionPane.showMessageDialog(this,"Registered successfully");}
 private void filter(){String selected=(String)event.getSelectedItem();model.setRowCount(0);for(String[]r:records)if(r[1].equals(selected))model.addRow(r);}
 private void exportCsv(){try(PrintWriter p=new PrintWriter(new FileWriter("registrations.csv"))){p.println("student_id,event");for(String[]r:records)p.println(r[0]+","+r[1]);JOptionPane.showMessageDialog(this,"Exported registrations.csv");}catch(IOException ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
 public static void main(String[]a){SwingUtilities.invokeLater(()->new EventRegistrationApp().setVisible(true));}}
